R=[
dict(no=74,q=r"모든 항이 자연수이고 다음 조건을 만족시키는 모든 수열 $\{a_n\}$에 대하여 $a_9$의 최댓값과 최솟값을 각각 $M$, $m$이라 할 때, $M+m$의 값은?",
 cond=r"(가) $a_7=40$\\(나) 모든 자연수 $n$에 대하여 $a_{n+2}=\begin{cases}a_{n+1}+a_n & (a_{n+1}\text{이 3의 배수가 아닌 경우})\\ \dfrac13a_{n+1} & (a_{n+1}\text{이 3의 배수인 경우})\end{cases}$이다.",
 ch=["216","218","220","222","224"],ans="5",fig=None,th="17",lk=["20"],
 fj=r"$a_9$는 $a_7=40$과 $a_8$로 정해지고 $a_8$은 $a_6$으로 정해지므로, $a_6$을 3으로 나눈 나머지로 경우를 나눈다.",
 bh="추론",rs=["경우 나누기","나열·역추적","정수 조건으로 후보 좁히기"],st=["S11"],
 sol=r"(i) $a_6$이 3의 배수: $a_6=120$, $a_8=160$, $a_9=200$. (ii) $a_6=3k-2$: $a_5=3(14-k)$, $a_6=\frac{a_5}3$ → $k=4$, $a_6=10$, $a_8=50$, $a_9=90$. (iii) $a_6=3k-1$: $a_5=41-3k$, $a_4=3(2k-14)$, $a_5=\frac{a_4}3$ → $k=11$, $a_6=32$, $a_8=72$, $a_9=24$. $M=200$, $m=24$, $M+m=224$"),
dict(no=75,q=r"수열 $\{a_n\}$은 $a_1=1$, $a_3=4$이고, 모든 자연수 $n$에 대하여 $a_{2n}=a_n+1$, $a_{4n+3}=a_{4n+1}=a_n+4$를 만족시킨다. $a_k=10$을 만족시키는 자연수 $k$의 개수를 구하시오.",
 cond=None,ch=None,ans="32",fig=None,th="21",lk=["17"],
 fj=r"$k$를 홀수($4n+1$, $4n+3$)와 짝수($2m$)로 나눠 $a_k=10$을 더 작은 값 $a_n=6$, $a_m=9$ 등의 개수 문제로 줄인다.",
 bh="문제해결",rs=["경우 나누기","나열·역추적"],st=["S11"],
 sol=r"표로 $a_n$의 값을 나열하면 $n\ge17$, $n\ne32$일 때 $a_n>6$. (i) $k$ 홀수: $a_n=6$인 $n$은 $9,10,11,12,14,32$의 6개, 각각 $4n+1$, $4n+3$ → 12개. (ii) $k$ 짝수: $k=4m$이면 $a_m=8$인 $m$ 개수 12, $k=8n+2$ 또는 $8n+6$이면 $a_n=5$인 $n$ 4개 → 8. 합 $12+20=32$",
 nr=["해설 중간 표(a_{4n+1}~a_{4n+4})는 요약함"]),
dict(no=76,q=r"수열 $\{a_n\}$은 $a_2=-a_1$이고, $n\ge2$인 모든 자연수 $n$에 대하여 $a_{n+1}=\begin{cases}a_n-\sqrt n\times a_{\sqrt n} & (\sqrt n\text{이 자연수이고 }a_n>0\text{인 경우})\\ a_n+1 & (\text{그 외의 경우})\end{cases}$을 만족시킨다. $a_{15}=1$이 되도록 하는 모든 $a_1$의 값의 곱을 구하시오.",
 cond=None,ch=None,ans="231",fig=None,th="20",lk=["21","17"],
 fj=r"$n=4,9$일 때만 특수 규칙이 적용되므로 $a_{15}=1$에서 $a_{10}=-4$까지 거꾸로 내려오고, $a_9$, $a_4$의 부호로 나눈다.",
 bh="문제해결",rs=["나열·역추적","경우 나누기"],st=["S11"],
 sol=r"$a_{14}=0,\dots,a_{10}=-4$. (i) $a_9>0$: $a_9-3a_3=-4$ → $a_9=3a_3-4$, $a_5=3a_3-8$. (i-a) $a_4>0$: $a_4-2a_2=a_5$, $a_3=a_2+1$ → $a_2=\frac74$, $a_1=-\frac74$. (i-b) $a_4\le0$: $a_3=5$ → $a_4=6>0$ 모순. (ii) $a_9\le0$: $a_5=-9$. (ii-a) $a_4>0$: $a_4=2a_2-9$, $a_2=11$, $a_1=-11$. (ii-b) $a_4\le0$: $a_4=-10$, $a_2=-12$, $a_1=12$. 곱 $-\frac74\cdot(-11)\cdot12=231$"),
dict(no=77,q=r"양수 $k$에 대하여 $a_1=k$인 수열 $\{a_n\}$이 다음 조건을 만족시킨다. $a_5=0$이 되도록 하는 서로 다른 모든 양수 $k$에 대하여 $k^2$의 값의 합을 구하시오.",
 cond=r"(가) $a_2a_3<0$\\(나) 모든 자연수 $n$에 대하여 $\left(a_{n+1}-a_n+\dfrac23k\right)(a_{n+1}+ka_n)=0$이다.",
 ch=None,ans="8",fig=None,th="21",lk=["17"],
 fj=r"매 단계 $a_{n+1}=a_n-\frac23k$ 또는 $-ka_n$의 두 갈래이므로 트리로 나열하되, (가)로 $a_2,a_3$ 부호가 다른 가지만 남긴다.",
 bh="문제해결",rs=["경우 나누기","나열·역추적"],st=["S11"],
 sol=r"$a_2=\frac k3$ 또는 $-k^2$. (i) $a_2=\frac k3$: $a_3=-\frac k3$ → $a_4=\frac{k^2}3$일 때 $a_5=\frac{k^2}3-\frac23k=0$, $k=2$; $a_3=-\frac{k^2}3$ → $a_4=\frac{k^3}3$일 때 $k=\sqrt2$. (ii) $a_2=-k^2$: $a_3=k^3$ → $a_4=k^3-\frac23k$일 때 $a_5=0$에서 $k=\frac2{\sqrt3}$ 또는 $\sqrt{\frac23}$. $k^2$의 합 $4+2+\frac43+\frac23=8$"),
dict(no=78,q=r"자연수 $k$에 대하여 다음 조건을 만족시키는 수열 $\{a_n\}$이 있다. $a_3\times a_4\times a_5\times a_6<0$이 되도록 하는 모든 $k$의 값의 합은?",
 cond=r"$a_1=k$이고, 모든 자연수 $n$에 대하여 $a_{n+1}=\begin{cases}a_n+2n-k & (a_n\le0)\\ a_n-2n-k & (a_n>0)\end{cases}$이다.",
 ch=["10","14","18","22","26"],ans="2",fig=None,th="17",lk=["21"],
 fj=r"$a_2=-2<0$이 $k$와 무관하게 정해지므로, 이후 항의 부호를 $k$의 범위로 나누며 나열한다.",
 bh="추론",rs=["경우 나누기","나열·역추적"],st=["S11"],
 sol=r"$a_2=-2$, $a_3=2-k$. (i) $k=1$: $a_3>0$, $a_4<0$, $a_5>0$, $a_6<0$ → 곱 $>0$. (ii) $k>2$: $a_4=8-2k$. (a) $k=3$: $a_4=2$, $a_5=-9$, $a_6=-2$ → 조건 만족. (b) $k>4$: $a_5=16-3k$; $k=5$: $a_5=1$, $a_6=-14$ → 만족; $k\ge6$: $a_6=26-4k>0$ → $k=6$. 합 $3+5+6=14$"),
dict(no=79,q=r"첫째항이 자연수인 수열 $\{a_n\}$이 모든 자연수 $n$에 대하여 $a_{n+1}=\begin{cases}2^{a_n} & (a_n\text{이 홀수인 경우})\\ \dfrac12a_n & (a_n\text{이 짝수인 경우})\end{cases}$를 만족시킬 때, $a_6+a_7=3$이 되도록 하는 모든 $a_1$의 값의 합은?",
 cond=None,ch=["139","146","153","160","167"],ans="3",fig=None,th="20",lk=["21"],
 fj=r"모든 항이 자연수이므로 $a_6+a_7=3$에서 $(a_6,a_7)=(1,2)$ 또는 $(2,1)$이고, 여기서 두 갈래 역함수로 $a_1$까지 거슬러 올라간다.",
 bh="문제해결",rs=["나열·역추적","경우 나누기"],st=["S11"],
 sol=r"(i) $a_6=1$: $a_5=2$, $a_4=1$ 또는 $4$, … 역추적하면 $a_1=2,6,8,32$. (ii) $a_6=2$: $a_2=2,6,8,32$에서 $a_1=1,4,12,3,16,5,64$. 합 $(2+6+8+32)+(1+3+4+5+12+16+64)=153$"),
dict(no=80,q=r"수열 $\{a_n\}$이 다음 조건을 만족시킨다. $|a_m|\ge5$를 만족시키는 $100$ 이하의 자연수 $m$의 개수를 $p$라 할 때, $p+a_1$의 값은?",
 cond=r"(가) 모든 자연수 $k$에 대하여 $a_{4k}=r^k$이다. (단, $r$는 $0<|r|<1$인 상수이다.)\\(나) $a_1<0$이고, 모든 자연수 $n$에 대하여 $a_{n+1}=\begin{cases}a_n+3 & (|a_n|<5)\\ -\dfrac12a_n & (|a_n|\ge5)\end{cases}$이다.",
 ch=["8","10","12","14","16"],ans="3",fig=None,th="20",lk=["17","18"],
 fj=r"$a_4=r$, $a_8=r^2$에서 출발해 $a_5,a_6,a_7,a_8$을 $r$로 나열하면 $r$이 결정되고, 이후 $a_3,a_2,a_1$은 역추적한다.",
 bh="문제해결",rs=["나열·역추적","단순화·특수화로 규칙성 찾기"],st=["S11"],
 sol=r"$a_4=r$, $|a_4|<5$ → $a_5=r+3$, $a_6=r+6$, $|a_6|\ge5$ → $a_7=-\frac r2-3$, $a_8=-\frac r2=r^2$ → $r=-\frac12$. 역추적: $a_3=-\frac72$, $a_2=7$, $a_1=-14$. 이후 $|a_{4k-2}|\ge5$, 즉 $m=1,2,6,10,\dots,98$ → $p=26$. $p+a_1=12$"),
dict(no=81,q=r"수열 $\{a_n\}$이 다음 조건을 만족시킨다. 다음은 $\displaystyle\sum_{k=1}^{12}a_k+\sum_{k=1}^{5}a_{2k+1}$의 값을 구하는 과정이다. 위의 (가)에 알맞은 식을 $f(n)$이라 하고, (나), (다)에 알맞은 수를 각각 $p,q$라 할 때, $\dfrac{pq}{f(12)}$의 값을 구하시오.",
 cond=r"[조건] $a_1=7$; $2$ 이상의 자연수 $n$에 대하여 $\displaystyle\sum_{k=1}^{n}a_k=\frac23a_n+\frac16n^2-\frac16n+10$이다.\\[과정] $2$ 이상의 자연수 $n$에 대하여 $a_{n+1}=\displaystyle\sum_{k=1}^{n+1}a_k-\sum_{k=1}^{n}a_k$이므로 $a_{n+1}=\dfrac23(a_{n+1}-a_n)+$ (가) 이고, 이 식을 정리하면 $2a_n+a_{n+1}=3\times$ (가) $\cdots$㉠ 이다. $\displaystyle\sum_{k=1}^{n}a_k=\frac23a_n+\frac16n^2-\frac16n+10$ $(n\ge2)$에서 양변에 $n=2$를 대입하면 $a_2=$ (나) $\cdots$㉡ 이다. ㉠과 ㉡에 의하여 $\displaystyle\sum_{k=1}^{12}a_k+\sum_{k=1}^{5}a_{2k+1}=a_1+a_2+\sum_{k=1}^{5}(2a_{2k+1}+a_{2k+2})=$ (다) 이다.",
 ch=None,ans="130",fig=None,th="16",lk=["17"],
 fj=r"$S_{n+1}-S_n$으로 $a_{n+1}$과 $a_n$의 관계식을 얻고, 구하는 합을 $2a_{2k+1}+a_{2k+2}$ 묶음으로 재배열한다.",
 bh="이해",rs=["조건의 식 번역"],st=["S10"],
 sol=r"(가) $\frac13n$ → $2a_n+a_{n+1}=n$. $n=2$: $a_1+\frac13a_2=\frac{31}3$ → $a_2=10$ (나). $\sum=a_1+a_2+\sum_{k=1}^5(2k+1)=7+10+35=52$ (다). $\frac{pq}{f(12)}=\frac{10\cdot52}{4}=130$"),
]
